// Glossary — auto-generated from curriculum
export const glossary = [
  { term: 'Activation Function', def: 'A non-linear function (e.g. ReLU, sigmoid, softmax) applied to a neuron\'s weighted sum; without one, stacking any number of linear layers collapses to a single linear transformation.' },
  { term: 'Agent', def: 'A system that generalizes the tool-calling loop to multi-step tasks, dynamically deciding what information or actions it needs across several iterations before producing a final answer.' },
  { term: 'Approximate Nearest Neighbor (ANN)', def: 'A class of search algorithms (e.g. HNSW) that trade a small amount of retrieval accuracy for a large speed improvement over brute-force similarity search at scale.' },
  { term: 'Autograd', def: 'PyTorch\'s automatic differentiation system, which tracks operations on tensors so gradients can be computed automatically via loss.backward(), replacing manual backpropagation.' },
  { term: 'Batching', def: 'Grouping multiple inference requests so a GPU processes them simultaneously instead of one at a time, dramatically improving throughput at some cost to individual-request latency.' },
  { term: 'Bias-Variance Trade-off', def: 'The tension between a model being too simple to capture real patterns (high bias, underfitting) and too sensitive to training-set noise (high variance, overfitting).' },
  { term: 'Broadcasting', def: 'NumPy\'s rule set for applying operations between arrays of different but compatible shapes without manually reshaping them, by stretching dimensions of size 1.' },
  { term: 'Causal Masking', def: 'A constraint in decoder-style transformers preventing a token from attending to tokens that come after it, required so training matches the one-token-at-a-time nature of generation.' },
  { term: 'Chain Rule', def: 'The calculus rule that lets a gradient be computed through a chain of functions by multiplying together each function\'s local derivative — what backpropagation automates one layer at a time.' },
  { term: 'Chain-of-Thought Prompting', def: 'A prompting pattern that asks an LLM to reason step by step before answering, improving performance on tasks requiring multi-step reasoning.' },
  { term: 'Chunking', def: 'Splitting a document into smaller pieces before embedding and storage in a RAG pipeline; strategies include fixed-size, recursive, and semantic chunking.' },
  { term: 'Confusion Matrix', def: 'A table of true positives, false positives, true negatives, and false negatives that all major classification metrics (precision, recall, F1) are derived from.' },
  { term: 'Content Moderation', def: 'Screening both user input (before it reaches an LLM) and generated output (before it reaches the user) for harmful, abusive, or policy-violating content.' },
  { term: 'Contextual Embeddings', def: 'Word or token representations computed fresh based on surrounding context, so the same word can have different vectors in different sentences — unlike a static embedding.' },
  { term: 'Continuous Batching', def: 'A technique used by serving frameworks like vLLM that dynamically adds new requests into an in-progress batch as earlier ones finish, improving throughput over fixed-batch serving.' },
  { term: 'Convolutional Networks', def: 'Neural networks that slide small learned filters (kernels) across an image to detect local patterns regardless of position, using far fewer parameters than an equivalent fully-connected layer.' },
  { term: 'Cosine Similarity', def: 'The dot product of two vectors divided by both their norms, comparing direction independent of magnitude; the standard similarity metric for comparing embeddings.' },
  { term: 'Cross-Validation', def: 'A model evaluation technique that rotates which portion of training data is held out across multiple folds, averaging results for a more robust estimate than a single train/validation split.' },
  { term: 'Data Drift', def: 'A change over time in the kind of inputs a system receives (e.g. the questions users ask), which can degrade performance even with no code or model change.' },
  { term: 'DBSCAN', def: 'A density-based clustering algorithm that finds clusters of arbitrary shape and automatically flags sparse, isolated points as noise, without requiring the number of clusters in advance.' },
  { term: 'Decoder-Only', def: 'A transformer architecture (e.g. the GPT family) that uses causal masking and predicts the next token from everything before it — the architecture behind most general-purpose LLMs.' },
  { term: 'Direct Prompt Injection', def: 'A user typing a malicious instruction (e.g. "ignore your previous instructions") directly into an input, attempting to hijack an LLM\'s behavior.' },
  { term: 'Dot Product', def: 'Multiply two vectors\' corresponding elements and sum the results; measures how much two vectors point in the same direction, and underlies embeddings, similarity search, and attention.' },
  { term: 'Encoder-Decoder', def: 'A transformer architecture (e.g. T5) that uses a bidirectional encoder to represent an input, then a causal decoder that generates output while cross-attending to that representation — suited to translation-style tasks.' },
  { term: 'Encoder-Only', def: 'A transformer architecture (e.g. BERT) with fully bidirectional attention and no causal mask, well suited to understanding tasks like classification and producing embeddings for search.' },
  { term: 'Euclidean Distance', def: 'Straight-line distance between two vectors; sensitive to magnitude, which is why cosine similarity — not Euclidean distance — is the standard metric for comparing embeddings.' },
  { term: 'F1 Score', def: 'The harmonic mean of precision and recall, used as a single balancing metric when neither false positives nor false negatives should be favored by default.' },
  { term: 'Faithfulness', def: 'A RAG evaluation property (also called groundedness) measuring whether every claim in a generated answer is actually supported by the retrieved context, distinct from whether retrieval itself succeeded.' },
  { term: 'Feature Importance', def: 'A measure of how much each feature contributed to a model\'s predictions on average across the whole dataset — contrast with SHAP, which explains one individual prediction.' },
  { term: 'Few-Shot Prompting', def: 'Including a small number of example input/output pairs in a prompt so the model infers a desired format or pattern, rather than relying on instructions alone.' },
  { term: 'Fine-Tuning', def: 'Updating a pretrained model\'s weights using a dataset of examples, baking a desired behavior into the model itself rather than specifying it via prompting at request time.' },
  { term: 'Forward Propagation', def: 'Running an input through a network layer by layer to produce an output — the same direction of computation used at inference time in production.' },
  { term: 'Gradient', def: 'A vector generalizing the derivative to functions with many inputs, pointing in the direction of steepest increase; used in gradient descent to update model parameters.' },
  { term: 'Gradient Boosting', def: 'An ensemble method that builds trees sequentially, each correcting the errors of the ensemble built so far; commonly implemented via XGBoost or LightGBM.' },
  { term: 'Gradient Descent', def: 'An optimization technique that repeatedly moves each parameter a small step opposite its gradient, gradually decreasing a loss function.' },
  { term: 'Groundedness', def: 'See Faithfulness — whether every claim in a generated answer is actually supported by the retrieved context.' },
  { term: 'HNSW (Hierarchical Navigable Small World)', def: 'A widely-used ANN algorithm that organizes vectors into a multi-layer graph, enabling fast approximate similarity search by navigating from sparse long-range connections to dense local ones.' },
  { term: 'Human-in-the-Loop (HITL)', def: 'A design pattern inserting an explicit human approval step before a high-stakes or hard-to-reverse agent action, rather than allowing fully autonomous execution.' },
  { term: 'Hybrid Search', def: 'Combining dense (vector/semantic) search with sparse (keyword, e.g. BM25) search so a query benefits from both semantic understanding and exact-term matching.' },
  { term: 'Indirect Prompt Injection', def: 'A malicious instruction planted in a document, web page, or tool result that a system will later retrieve or fetch — more dangerous than direct injection because the attacker never interacts with the system.' },
  { term: 'K-Means Clustering', def: 'A clustering algorithm that assigns points to a chosen number (k) of clusters and iteratively recenters them; requires k in advance and assumes roughly round, similarly-sized clusters.' },
  { term: 'LangGraph', def: 'A framework for defining an agent\'s control flow explicitly as a graph of nodes (steps) and edges (transitions, including conditional routing based on state).' },
  { term: 'LLM-as-Judge', def: 'A technique using a separate LLM call to score properties like faithfulness or answer relevance at scale, as a more scalable alternative to manual review.' },
  { term: 'Logit', def: 'A raw, unnormalized score an LLM produces for each possible next token, before softmax converts these scores into a probability distribution.' },
  { term: 'LoRA (Low-Rank Adaptation)', def: 'A parameter-efficient fine-tuning method that trains small low-rank matrices alongside a model\'s frozen original weights, dramatically reducing the number of trainable parameters.' },
  { term: 'Metadata Filtering', def: 'Combining vector similarity search with exact-match conditions on structured fields (e.g. document category, publish date, or user authorization), applied at the database query level.' },
  { term: 'Model Drift', def: 'A change over time in a model\'s behavior with no code change on your part — for example, a hosted provider updating the model behind a "latest" alias.' },
  { term: 'Model Routing', def: 'Using a cheap, fast model to classify how complex a request is, then routing only genuinely complex requests to a larger, more expensive model.' },
  { term: 'MRR (Mean Reciprocal Rank)', def: 'A retrieval metric rewarding how highly the first relevant result is ranked, important because lower-ranked results are more likely to be excluded from the final context sent to an LLM.' },
  { term: 'Multi-Head Attention', def: 'Running several independent attention computations in parallel, each with its own learned projections, potentially specializing in different token relationships, then combining their outputs.' },
  { term: 'Neuron', def: 'A neural network\'s basic unit: a weighted sum of its inputs plus a bias term, passed through an activation function.' },
  { term: 'Overfitting', def: 'When a model learns the noise specific to its training data rather than the underlying pattern, performing well on training data but poorly on new data.' },
  { term: 'Parameter Sharing', def: 'Reusing the same small kernel across an entire image in a convolutional network, rather than learning a separate weight per pixel position — the main reason CNNs need far fewer parameters than an equivalent fully-connected layer.' },
  { term: 'Parameter-Efficient Fine-Tuning (PEFT)', def: 'A family of fine-tuning methods (LoRA, QLoRA, prefix-tuning, prompt-tuning) that update only a small number of additional parameters while keeping most of a model\'s weights frozen.' },
  { term: 'PCA (Principal Component Analysis)', def: 'A dimensionality-reduction technique that projects data onto the directions along which it varies most, useful for visualization or for simplifying inputs to another model.' },
  { term: 'Pooling', def: 'Reducing a convolutional feature map\'s size (typically by keeping only the largest value in each small region) while preserving its strongest signal and adding tolerance to small positional shifts.' },
  { term: 'Positional Encoding', def: 'A position-dependent signal added to token embeddings before attention, giving a transformer information about token order that attention alone does not inherently capture.' },
  { term: 'Precision', def: 'Of the items a system predicted or retrieved as positive/relevant, the fraction that actually were — paired with recall to judge classification or retrieval quality, since either alone can be misleading.' },
  { term: 'Privilege Separation', def: 'The core defense against prompt injection: keeping trusted instructions (the system prompt) clearly and consistently separated from untrusted content (user input, retrieved documents, tool results) in both architecture and prompt structure.' },
  { term: 'Prompt Caching', def: 'A provider feature that reuses previously-processed computation for a long, identical prompt prefix shared across requests, reducing cost and latency.' },
  { term: 'Prompt Injection', def: 'An attack where text crafted to look like an instruction is placed somewhere an LLM will read it, hijacking its behavior; can be direct (typed by a user) or indirect (planted in retrieved content).' },
  { term: 'Quantization', def: 'Reducing the numerical precision used to store model weights (e.g. 16-bit to 4-bit), shrinking memory footprint and often speeding up inference at a small cost to output quality.' },
  { term: 'Random Forests', def: 'An ensemble of many decision trees trained on different random subsets of data and features, then averaged together — diverse overfitting patterns cancel out.' },
  { term: 'Rate Limiting', def: 'Capping how many requests or tokens a user or API key can consume in a given time window, protecting against abuse and runaway cost, especially important for LLM-backed endpoints.' },
  { term: 'Recall', def: 'Of the items that are actually relevant or positive, the fraction a system successfully identified or retrieved — used both for classification (recall of a class) and retrieval (recall of relevant chunks).' },
  { term: 'ReLU', def: 'An activation function returning zero for negative inputs and the input itself for positive ones; the modern default for hidden layers because it is cheap to compute and trains well.' },
  { term: 'Reflection', def: 'A pattern where a separate LLM call reviews and critiques prior generated output before it is finalized, catching a different set of errors than the original generation pass alone.' },
  { term: 'Regression Suite', def: 'A fixed, versioned set of test tasks run automatically whenever an agent\'s prompt, tools, or model changes, catching a silent behavior change the way a code regression suite catches an unintended side effect.' },
  { term: 'Reranking', def: 'A second retrieval stage where a more expensive, more precise model re-scores the initial candidate results before only the top few are passed to the LLM.' },
  { term: 'Retrieval-Augmented Generation (RAG)', def: 'An architecture that retrieves relevant source material at query time and provides it to an LLM as context, grounding generated answers in that material rather than relying purely on training data.' },
  { term: 'ROC-AUC', def: 'A metric measuring how well a model ranks positive examples above negative ones across all possible classification thresholds — threshold-independent, useful for comparing models rather than setting an operating point.' },
  { term: 'Self-Attention', def: 'The core transformer mechanism that lets each token weigh the relevance of every other token via Query/Key/Value projections, a scaled dot product, softmax, and a weighted sum of Values.' },
  { term: 'Server-Sent Events (SSE)', def: 'A standard mechanism for a long-lived HTTP response to send a sequence of small text-formatted events over time, used to stream generated tokens to a client progressively.' },
  { term: 'SHAP', def: 'A technique attributing one individual prediction\'s outcome to specific feature contributions for that specific example — contrast with feature importance, which describes overall model behavior.' },
  { term: 'Softmax', def: 'A function that converts raw scores into a probability distribution summing to 1; used both to produce class probabilities in classification and to produce next-token probabilities in LLMs.' },
  { term: 'Streaming', def: 'Sending generated tokens to a client progressively as they are produced, rather than waiting for the full response, reducing perceived latency for chat-style interactions.' },
  { term: 'Task Success Rate', def: 'Across a set of representative test tasks, the fraction an agent completed correctly — the most basic agent evaluation metric, though it hides which specific tasks or tools are failing.' },
  { term: 'Temperature', def: 'A sampling parameter that reshapes an LLM\'s next-token probability distribution before sampling; low temperature sharpens it toward the most likely tokens, high temperature flattens it toward more randomness.' },
  { term: 'Tokenization', def: 'Splitting text into model-processable units (often subwords) mapped to a fixed vocabulary, the first step in converting text into a form an LLM or embedding model can process.' },
  { term: 'Tool Calling', def: 'A mechanism letting an LLM request that an external function be executed with specific arguments; the model only decides what to call, the application executes it.' },
  { term: 'Tool-Call Correctness', def: 'Whether an agent called the correct tool with correct arguments at each step, independent of whether the final answer happened to be right — catches a fragile "right answer, wrong path" success.' },
  { term: 'Top-k', def: 'A sampling restriction that limits next-token selection to only the k highest-probability tokens.' },
  { term: 'Top-p', def: 'Nucleus sampling: a sampling restriction that includes just enough top tokens for their combined probability to reach a threshold p, adapting the candidate pool size to how confident the distribution is.' },
  { term: 'Tracing', def: 'Recording the full sequence of events in one agent run — every LLM call, tool call, and state transition — as a structured, timestamped log, used to debug why a specific run went wrong.' },
  { term: 'Vector Database', def: 'A specialized data store for embedding vectors that supports efficient similarity search, typically via an ANN index (e.g. HNSW), often alongside metadata filtering.' },
  { term: 'Vectorization', def: 'Expressing an operation as a whole-array operation instead of a Python loop, letting NumPy operate on a whole block of memory at once for large speed gains.' },
  { term: 'Zero-Shot Prompting', def: 'Asking a model to perform a task with only an instruction and no examples — works well when the task is common and the instruction is unambiguous.' },
]
